<template>
  <div class="demo-preview" data-demo-preview>
    <button
      ref="exitButton"
      type="button"
      class="demo-preview__exit"
      title="退出全屏（Esc）"
      aria-label="退出全屏"
      @click.stop="exitFullscreen"
    >
      <svg
        class="demo-preview__exit-icon"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        <path
          d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3"
        />
      </svg>
      <span class="demo-preview__exit-text">退出全屏</span>
    </button>
    <slot />
  </div>
</template>

<script setup lang="ts">
import { nextTick, ref, watch } from 'vue'
import { useDemoFullscreen } from '../composables/useDemoFullscreen'

/**
 * 组件预览区：全屏按钮的唯一目标。
 *
 * 普通模式下它只是页面里的一个普通容器；进入全屏后由 vue-fullscreen 给根节点
 * 加上 is-demo-fullscreen 类，只保留插槽里的组件内容，页面标题、简介、说明与
 * 页脚都不会进入全屏。右下角的「退出全屏」按钮也只在全屏时出现。
 */
const { isFullscreen, exit } = useDemoFullscreen()
const exitButton = ref<HTMLButtonElement | null>(null)

// 进入全屏后把焦点移到「退出全屏」，键盘用户可以直接 Esc / Enter 退出
watch(isFullscreen, async (value) => {
  if (!value) return
  await nextTick()
  exitButton.value?.focus({ preventScroll: true })
})

function exitFullscreen() {
  exit().catch((error) => {
    console.warn('[Fullscreen] Failed to exit fullscreen:', error)
  })
}
</script>
